mapper.select:
select 
from oa_sign_task
where scenario = #{scenario}
  and employee_id = #{employeeId}
  and source_type = #{sourceType}
  and source_business_id = #{sourceBusinessId}
  and source_event_version = #{sourceEventVersion}
order by case
  when package_id is not null and plan_version_id is not null then 0
  else 1
end asc, task_id asc
limit 1

select ,
       (select p.employee_name_snapshot
          from oa_sign_package p
         where p.package_id = oa_sign_task.package_id
         limit 1) as employee_name
from oa_sign_task

    and task_id = #{taskId}
    and task_no = #{taskNo}

        and (scenario = #{scenario}
             or (upper(#{scenario}) = 'RENEWAL' and upper(trim(scenario)) = 'RENEW'))

    and employee_id = #{employeeId}

        and exists (
            select 1 from oa_sign_package p
            where p.package_id = oa_sign_task.package_id
              and p.employee_name_snapshot like concat('%', #{employeeName}, '%')
        )

    and assigned_hr_user_id = #{assignedHrUserId}
    and status = #{status}

        and status in ('PENDING_SIGN', 'VIEWED', 'PENDING_FINAL_CONFIRM')
        and sign_deadline >= sysdate()
        and sign_deadline <= date_add(sysdate(), interval 3 day)


        and status = 'SIGNED'
        and completed_time >= date_format(current_date, '%Y-%m-01')
        and completed_time < date_add(last_day(current_date), interval 1 day)

    and shop_dept_id = #{shopDeptId}

        and shop_dept_id in

            #{scopeDeptId}



order by created_time desc, task_id desc

select t.* from oa_sign_task t inner join ( select employee_id, max(task_id) as task_id from oa_sign_task where upper(trim(scenario)) = 'ONBOARD' and employee_id in
#{employeeId}
group by employee_id ) latest on latest.task_id = t.task_id order by t.employee_id asc

select coalesce(sum(case when status = 'NEEDS_DATA' then 1 else 0 end), 0) as needs_data, coalesce(sum(case when status = 'PENDING_COMPANY' then 1 else 0 end), 0) as waiting_hr_confirm, coalesce(sum(case when status = 'FAILED' then 1 else 0 end), 0) as failed, coalesce(sum(case when status = 'VIEWED' then 1 else 0 end), 0) as viewed, coalesce(sum(case when status IN ('PENDING_SIGN', 'VIEWED', 'PENDING_FINAL_CONFIRM') and sign_deadline >= sysdate() and sign_deadline <= date_add(sysdate(), interval 3 day) then 1 else 0 end), 0) as due_soon, coalesce(sum(case when status = 'REFUSED' then 1 else 0 end), 0) as refused, coalesce(sum(case when status = 'SIGNED' and completed_time >= date_format(current_date, '%Y-%m-01') and completed_time < date_add(last_day(current_date), interval 1 day) then 1 else 0 end), 0) as completed_month from oa_sign_task
and assigned_hr_user_id = #{assignedHrUserId} and shop_dept_id = #{shopDeptId}
and shop_dept_id in
#{scopeDeptId}

mapper.update:
update oa_sign_task
set status = #{toStatus},
    version = version + 1,
    failure_code = #{failureCode},
    failure_detail = #{failureDetail},
    next_retry_time = #{nextRetryTime}
where task_id = #{taskId}
  and assigned_hr_user_id = #{assignedHrUserId}
  and status = #{fromStatus}
  and version = #{version}

update oa_sign_task
set status = #{toStatus},
    version = version + 1,
    retry_count = retry_count + 1,
    failure_code = #{failureCode},
    failure_detail = #{failureDetail},
    next_retry_time = #{nextRetryTime}
where task_id = #{taskId}
  and assigned_hr_user_id = #{assignedHrUserId}
  and status = #{fromStatus}
  and version = #{version}

update oa_sign_task
set confirmed_by = #{confirmedBy},
    confirmed_time = #{confirmedTime},
    confirmed_snapshot_hash = #{confirmedSnapshotHash}
where task_id = #{taskId}
  and assigned_hr_user_id = #{assignedHrUserId}
  and status = #{expectedStatus}
  and version = #{version}
  and confirmed_by is null

update oa_sign_task
set confirmed_by = null,
    confirmed_time = null,
    confirmed_snapshot_hash = null
where task_id = #{taskId}
  and assigned_hr_user_id = #{assignedHrUserId}
  and status = #{expectedStatus}
  and version = #{version}

update oa_sign_task
set package_id = #{packageId},
    plan_version_id = #{planVersionId},
    risk_level = #{riskLevel}
where task_id = #{taskId}
  and package_id is null
  and plan_version_id is null
  and assigned_hr_user_id = #{assignedHrUserId}
  and status = 'VALIDATING'
  and version = #{version}
  and exists (
      select 1
      from oa_sign_package p
      where p.package_id = #{packageId}
        and p.task_id = oa_sign_task.task_id
        and p.plan_version_id = #{planVersionId}
  )

update oa_sign_task
set plan_version_id = #{planVersionId},
    risk_level = #{riskLevel},
    version = version + 1
where task_id = #{taskId}
  and package_id is null
  and plan_version_id is null
  and assigned_hr_user_id = #{assignedHrUserId}
  and status = 'VALIDATING'
  and version = #{version}

update oa_sign_task
set risk_level = #{riskLevel}
where task_id = #{taskId}
  and package_id is null
  and plan_version_id is null
  and assigned_hr_user_id = #{assignedHrUserId}
  and status = 'VALIDATING'
  and version = #{version}
  and confirmed_by is null
  and confirmed_time is null
  and confirmed_snapshot_hash is null

update oa_sign_task
set sent_time = #{sentTime}
where task_id = #{taskId}

update oa_sign_task
set sent_time = #{sentTime},
    sign_deadline = #{signDeadline},
    deadline_policy_source = #{deadlinePolicySource},
    deadline_days_snapshot = #{deadlineDaysSnapshot}
where task_id = #{taskId}
  and status = #{expectedStatus}
  and version = #{version}
  and assigned_hr_user_id = #{assignedHrUserId}
  and sent_time is null
  and sign_deadline is null

update oa_sign_task
set sign_deadline = #{signDeadline},
    version = version + 1
where task_id = #{taskId}
  and status = #{expectedStatus}
  and #{expectedStatus} = 'PENDING_COMPANY'
  and version = #{version}
  and assigned_hr_user_id = #{assignedHrUserId}
  and sign_deadline = #{currentDeadline}
  and #{signDeadline} > #{currentDeadline}
  and deadline_policy_source is not null
  and trim(deadline_policy_source) != ''
  and deadline_days_snapshot > 0

update oa_sign_task
set completed_time = #{completedTime}
where task_id = #{taskId}

mapper.delete:
delete from oa_sign_task
where task_id = #{taskId}
  and version = #{expectedVersion}
